471	import { EXAMPLE_ROSTER } from './hero.example-data';
472	import type { Hero } from './hero.model';
473	
474	/**
475	 * In-memory hero store. Holds EXAMPLE DATA (see `hero.example-data.ts`) as signal
476	 * state; there is no backend, so updates last only until the page reloads.
477	 */
478	@Service()
479	export class HeroService {
480	  private readonly heroes = signal<readonly Hero[]>(EXAMPLE_ROSTER);
481	
482	  /** The full roster, read-only. */
483	  readonly list = this.heroes.asReadonly();
484	  readonly count = computed(() => this.heroes().length);
485	
486	  /** Looks up a hero by id. Reads the signal, so calling it inside a `computed` stays reactive. */
487	  byId(id: string): Hero | undefined {
488	    return this.heroes().find((hero) => hero.id === id);
489	  }
490	
491	  /**
492	   * Applies a partial update to the hero with `id` and returns the stored record,
493	   * or `undefined` if no hero has that id. The id itself cannot be changed.
494	   */
495	  update(id: string, patch: Partial<Omit<Hero, 'id'>>): Hero | undefined {
496	    const current = this.byId(id);
497	    if (!current) {
498	      return undefined;
499	    }
500	    const next: Hero = { ...current, ...patch };
501	    this.heroes.update((list) => list.map((hero) => (hero.id === id ? next : hero)));
502	    return next;
503	  }
504	
505	  /** Removes the hero with `id` from the roster. Returns `false` if no hero has that id. */
506	  retire(id: string): boolean {
507	    if (!this.byId(id)) {
508	      return false;
509	    }
510	    this.heroes.update((list) => list.filter((hero) => hero.id !== id));
511	    return true;
512	  }
513	}
