542	import type { FormFieldMeta } from './form-field-meta';
543	
544	/**
545	 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
546	 * control kind, and placeholder on the schema (one source of truth) so a form
547	 * component reads them instead of restating them. Pair with `validateStandardSchema`
548	 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
549	 * live on the one schema.
550	 */
551	export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
552	  const meta: Record<string, FormFieldMeta> = {};
553	  for (const [name, field] of Object.entries(schema.shape)) {
554	    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
555	  }
556	  return meta;
557	}
