1293	          (needle === '' || [hero.name, hero.alias, hero.id].some((field) => field.toLowerCase().includes(needle))),
1294	      )
1295	      .sort((a, b) => b.powerIndex - a.powerIndex)
1296	      .map((hero) => ({
