// One-off end-to-end check of the shared-state flows. Lives outside the repo; run from there.
import { join } from 'node:path';
import { serveStatic, launchChromium } from 'file:///D:/Repos/angular-jig/harness/playwright/serve-and-visit.mjs';

const DIST = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const srv = await serveStatic(DIST);
const browser = await launchChromium();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

const check = (cond, msg) => { console.log((cond ? 'PASS ' : 'FAIL ') + msg); if (!cond) process.exitCode = 1; };
const navTo = async (name) => page.locator('a', { hasText: name }).first().click();

try {
  // 1. Edit a hero on the detail screen.
  await page.goto(`${srv.origin}/detail/HRO-0012`);
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.locator('#hero-name').fill('Dr. Ion Prime');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.getByText('Saved changes to Dr. Ion Prime.').waitFor({ timeout: 5000 });
  check(true, 'detail edit saved with notice');

  // 2. Client-side navigation keeps the in-memory state.
  await navTo('Dashboard');
  await page.getByRole('heading', { name: 'Operations Dashboard' }).waitFor();
  const dashText = await page.locator('main').innerText();
  check(dashText.includes('Dr. Ion Prime'), 'dashboard shows the edited name');

  await navTo('Roster');
  await page.getByRole('heading', { name: 'Roster', exact: true }).waitFor();
  check((await page.locator('main').innerText()).includes('Dr. Ion Prime'), 'roster shows the edited name');

  // 3. Recruit a hero; it should land on its detail page and count on the roster.
  await page.getByRole('link', { name: 'Recruit' }).first().click();
  await page.locator('#recruit-name').fill('Test Recruit');
  await page.locator('#recruit-alias').fill('Test Alias');
  await page.locator('#recruit-power').fill('55');
  await page.locator('#recruit-clearance').fill('2');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.getByRole('heading', { name: 'Test Recruit' }).waitFor({ timeout: 5000 });
  check(page.url().includes('/detail/HRO-0076'), 'recruit lands on new detail page: ' + page.url());

  await navTo('Roster');
  await page.getByRole('heading', { name: 'Roster', exact: true }).waitFor();
  check((await page.locator('main').innerText()).includes('14 of 14 heroes'), 'roster count rose to 14');

  // 4. Deploy from Missions: the mission count on the record rises by one.
  await navTo('Missions');
  await page.getByRole('heading', { name: 'Missions', exact: true }).waitFor();
  await page.getByRole('button', { name: 'Deploy Dr. Ion Prime' }).click();
  await page.getByText('Dr. Ion Prime deployed.').waitFor({ timeout: 5000 });
  check(true, 'missions deploy notice shown');

  // 5. Threats board and settings render real content.
  await navTo('Threats');
  await page.getByRole('heading', { name: 'Threat board' }).waitFor();
  check((await page.locator('main').innerText()).includes('7 open of 9'), 'threat board shows 7 open of 9');
  await navTo('Settings');
  await page.getByRole('heading', { name: 'Settings', exact: true }).waitFor();
  check((await page.locator('main').innerText()).includes('Heroes on roster'), 'settings renders');
} catch (e) {
  console.log('FAIL flow threw: ' + e.message.split('\n')[0]);
  process.exitCode = 1;
} finally {
  if (errors.length) console.log('console errors:\n  ' + errors.join('\n  '));
  await browser.close();
  await srv.close();
}

